CREATE TABLE IF NOT EXISTS gis_phase349_provenance_audit (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, candidate_id UUID NOT NULL, source_feature_id UUID NOT NULL, target_feature_id UUID NOT NULL, source_provider TEXT, target_provider TEXT, source_geometry_type TEXT, target_geometry_type TEXT, source_crs TEXT, target_crs TEXT, source_coordinate_domain TEXT, target_coordinate_domain TEXT, same_provider BOOLEAN, same_geometry_type BOOLEAN, crs_compatible BOOLEAN, provenance_status TEXT NOT NULL, issues JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,candidate_id));